:root {
  --bg: #1a1a2e;
  --card-bg: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --snake: #0f3460;
  --food: #e94560;
  --grid: #1a1a2e;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  color: var(--text);
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-card {
  background: var(--card-bg);
  border-radius: 16px;
  padding: 24px;
  width: 100%;
  max-width: 480px;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.game-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

h1 {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
  letter-spacing: 1px;
}

.score-display {
  font-size: 1.25rem;
  font-weight: 600;
  background: var(--bg);
  padding: 6px 14px;
  border-radius: 8px;
}

.canvas-wrapper {
  position: relative;
  width: 100%;
  aspect-ratio: 1 / 1;
  background: var(--grid);
  border-radius: 8px;
  overflow: hidden;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}

.overlay {
  position: absolute;
  inset: 0;
  background: rgba(22, 33, 62, 0.95);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 12px;
  padding: 24px;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.2s;
}

.overlay.visible {
  opacity: 1;
  pointer-events: auto;
}

.overlay h2 {
  font-size: 1.5rem;
  color: var(--accent);
}

.overlay p {
  font-size: 1rem;
  line-height: 1.5;
  max-width: 300px;
}

.btn {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 24px;
  border: 2px solid var(--accent);
  border-radius: 8px;
  background: transparent;
  color: var(--text);
  cursor: pointer;
  transition: background 0.15s, transform 0.1s;
}

.btn:hover {
  background: var(--accent);
  color: var(--bg);
}

.btn:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.97);
}

.btn.primary {
  background: var(--accent);
  color: var(--bg);
}

.btn.primary:hover {
  background: #ff6b81;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.controls .btn {
  flex: 1;
  min-width: 120px;
}

@media (max-width: 400px) {
  .game-card {
    padding: 16px;
  }
  h1 {
    font-size: 1.25rem;
  }
  .score-display {
    font-size: 1rem;
  }
  .btn {
    padding: 10px 16px;
    font-size: 0.95rem;
  }
}

(function () {
  'use strict';

  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const scoreEl = document.getElementById('score');
  const finalScoreEl = document.getElementById('final-score');
  const overlay = document.getElementById('overlay');
  const gameoverEl = document.getElementById('gameover');
  const startBtn = document.getElementById('start-btn');
  const pauseBtn = document.getElementById('pause-btn');
  const restartBtn = document.getElementById('restart-btn');
  const restartGameoverBtn = document.getElementById('restart-gameover');

  const GRID = 20;
  const CELL = canvas.width / GRID;

  let snake, direction, nextDirection, food, score, running, paused, gameOver, loopId;

  function init() {
    snake = [{ x: 10, y: 10 }];
    direction = { x: 1, y: 0 };
    nextDirection = { x: 1, y: 0 };
    score = 0;
    gameOver = false;
    running = false;
    paused = true;
    scoreEl.textContent = '0';
    spawnFood();
    draw();
    updateUI();
  }

  function spawnFood() {
    let pos;
    do {
      pos = {
        x: Math.floor(Math.random() * GRID),
        y: Math.floor(Math.random() * GRID)
      };
    } while (snake.some(s => s.x === pos.x && s.y === pos.y));
    food = pos;
  }

  function draw() {
    ctx.fillStyle = '#1a1a2e';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // grid lines
    ctx.strokeStyle = '#16213e';
    ctx.lineWidth = 1;
    for (let i = 1; i < GRID; i++) {
      ctx.beginPath();
      ctx.moveTo(i * CELL, 0);
      ctx.lineTo(i * CELL, canvas.height);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(0, i * CELL);
      ctx.lineTo(canvas.width, i * CELL);
      ctx.stroke();
    }

    // food
    ctx.fillStyle = '#e94560';
    ctx.fillRect(food.x * CELL + 1, food.y * CELL + 1, CELL - 2, CELL - 2);

    // snake
    snake.forEach((seg, i) => {
      ctx.fillStyle = i === 0 ? '#4e9f3d' : '#0f3460';
      ctx.fillRect(seg.x * CELL + 1, seg.y * CELL + 1, CELL - 2, CELL - 2);
    });
  }

  function update() {
    if (!running || paused || gameOver) return;

    direction = nextDirection;
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= GRID || head.y < 0 || head.y >= GRID) {
      endGame();
      return;
    }
    if (snake.some(s => s.x === head.x && s.y === head.y)) {
      endGame();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score += 10;
      scoreEl.textContent = score;
      spawnFood();
    } else {
      snake.pop();
    }

    draw();
  }

  function endGame() {
    gameOver = true;
    running = false;
    finalScoreEl.textContent = score;
    gameoverEl.classList.add('visible');
    updateUI();
  }

  function startLoop() {
    if (loopId) clearInterval(loopId);
    loopId = setInterval(update, 120);
  }

  function startGame() {
    init();
    running = true;
    paused = false;
    overlay.classList.remove('visible');
    gameoverEl.classList.remove('visible');
    startLoop();
    updateUI();
  }

  function togglePause() {
    if (!running || gameOver) return;
    paused = !paused;
    updateUI();
  }

  function restart() {
    if (loopId) clearInterval(loopId);
    startGame();
  }

  function updateUI() {
    pauseBtn.textContent = paused ? 'Resume' : 'Pause';
    pauseBtn.setAttribute('aria-label', paused ? 'Resume game' : 'Pause game');
    pauseBtn.disabled = !running || gameOver;
  }

  function handleKey(e) {
    const key = e.key;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', ' '].includes(key)) {
      e.preventDefault();
    }

    if (key === ' ' || key === 'Spacebar') {
      if (!running && !gameOver) {
        startGame();
      } else if (running && !gameOver) {
        togglePause();
      }
      return;
    }

    if (!running || paused || gameOver) return;

    const dirs = {
      ArrowUp: { x: 0, y: -1 },
      ArrowDown: { x: 0, y: 1 },
      ArrowLeft: { x: -1, y: 0 },
      ArrowRight: { x: 1, y: 0 }
    };

    const nd = dirs[key];
    if (!nd) return;
    if (nd.x === -direction.x && nd.y === -direction.y) return;
    nextDirection = nd;
  }

  startBtn.addEventListener('click', startGame);
  pauseBtn.addEventListener('click', togglePause);
  restartBtn.addEventListener('click', restart);
  restartGameoverBtn.addEventListener('click', startGame);
  document.addEventListener('keydown', handleKey);

  init();
})();
